+  useEffect(() => {
+    if (!analyse) return;
+    let data;
+    try { data = dataStr.trim() === "" ? {} : loadYaml(dataStr); }
+    catch (e) { setAnalyseRes({ ok: false, error: "data isn’t valid YAML — " + ((e && e.message) || e), findings: [], suppressed: 0 }); return; }
