+/* Live `flatbars analyse` pane (opt-in): the same always-dark screen as the lint
+   pane, but the findings are STRUCTURED (kind-grouped) rather than raw report
+   text — observed/potential/miss each get a labelled group. Fixed colours for the
+   same reason as lint (the screen is dark in both themes). */
+.oil .oil-an {
+  background: var(--out-bg);
+  color: var(--out-fg);
+  border: 1px solid #000;
+  border-radius: var(--radius);
+  padding: 0.6rem 0.75rem;
+  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
+  font: 400 0.82rem/1.5 var(--font-mono);
+}
+.oil .oil-an-head { color: #c9c9d4; margin-bottom: 0.5rem; }
+.oil .oil-an-supp { color: #86efac; }
+.oil .oil-an-empty {
+  background: var(--out-bg); color: #9a9a9a; border: 1px solid #000;
+  border-radius: var(--radius); padding: 0.7rem 0.85rem; font: 400 0.82rem/1.5 var(--font-mono);
+}
+.oil .oil-an-empty.err { color: #ff9c9c; }
+.oil .oil-an-grp { margin-top: 0.55rem; padding-left: 0.6rem; border-left: 2px solid #3a3a48; }
+.oil .oil-an-observed { border-left-color: #fbbf24; }
+.oil .oil-an-potential { border-left-color: #7dd3fc; }
+.oil .oil-an-miss { border-left-color: #c4b5fd; }
+.oil .oil-an-grp-head { color: #9a9aa6; font-size: 0.76rem; margin-bottom: 0.3rem; }
+.oil .oil-an-grp-head b { color: #e6e6ef; }
+.oil .oil-an-row { padding: 0.25rem 0; }
+.oil .oil-an-row + .oil-an-row { border-top: 1px solid rgba(255, 255, 255, 0.06); }
+.oil .oil-an-tag { color: #fbbf24; background: none; padding: 0; margin-right: 0.4rem; }
+.oil .oil-an-val { color: var(--out-fg); }
+.oil .oil-an-flips { color: #9a9aa6; }
+.oil .oil-an-fix { display: block; color: #8fa6b8; font-size: 0.76rem; margin-top: 0.1rem; }
+
+/* The editable safe-paths input (the `pathSchemaDemo` card only): a small field
+   above the findings that feeds analyzeWith live. */
+.oil .oil-schema { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.55rem; }
+.oil .oil-schema-cap {
+  font: 600 11px/1 var(--font-mono); letter-spacing: 0.03em; color: var(--fg-faint);
+  text-transform: none; white-space: nowrap;
+}
+.oil .oil-schema-in {
+  flex: 1; min-width: 0; font: 400 0.8rem/1.4 var(--font-mono);
+  background: var(--out-bg); color: var(--out-fg);
+  border: 1px solid #000; border-radius: 6px; padding: 0.35rem 0.55rem;
+}
+.oil .oil-schema-in:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
+.oil .oil-schema-in::placeholder { color: #6b6b78; }
+
 /* The shared catalog reference (top of the Localize guide): the same card chrome
    as an example, anchored with an accent edge so it reads as the one source every
    card below pulls from. */
